export class WeekPicker {
  readonly week = input.required<WeekRange>();
  readonly earliestWeek = input.required<string>();
  readonly latestCompleteWeek = input.required<string>();

  readonly weekSelected = output<string>();

  private readonly injector = inject(Injector);
  private readonly trigger = viewChild.required<ElementRef<HTMLButtonElement>>('trigger');
  private readonly calendar = viewChild(MatCalendar);

  protected readonly dialogId = `week-picker-dialog-${nextDialogId++}`;
  protected readonly popoverPositions: ConnectedPosition[] = [
    { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 8 },
    { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -8 },
  ];

  protected readonly isOpen = signal(false);
  protected readonly isDisabled = computed(() => this.earliestWeek() === this.latestCompleteWeek());
  protected readonly weekLabel = computed(() => formatWeekRange(this.week().start, this.week().end));
  protected readonly triggerName = computed(() => `${this.weekLabel()}, choose week`);
  protected readonly selectableWeeksLabel = computed(() => formatSelectableWeeks(this.earliestWeek(), this.latestCompleteWeek()));
  protected readonly isLatestWeekSelected = computed(() => this.week().start === this.latestCompleteWeek());
  protected readonly selectedMonday = computed(() => parseISO(this.week().start));
  protected readonly earliestMonday = computed(() => parseISO(this.earliestWeek()));
  protected readonly latestCompleteMonday = computed(() => parseISO(this.latestCompleteWeek()));

  protected readonly isSelectableMonday: DateFilterFn<Date> = (day) => day !== null && isMonday(day);

  protected readonly selectedWeekClass: MatCalendarCellClassFunction<Date> = (day, view) =>
    view === 'month' && isSameWeek(day, this.selectedMonday(), { weekStartsOn: 1 }) && !isMonday(day) ? SELECTED_WEEK_CLASS : '';

  protected toggle(): void {
    if (this.isOpen()) {
      this.close();
    } else {
      this.isOpen.set(true);
    }
  }

  protected close(): void {
    if (!this.isOpen()) {
      return;
    }
    this.isOpen.set(false);
    this.trigger().nativeElement.focus();
  }

  protected closeOnOutsideClick(event: MouseEvent): void {
    if (!(event.target instanceof Node && this.trigger().nativeElement.contains(event.target))) {
      this.close();
    }
  }

  protected focusSelectedWeek(): void {
    afterNextRender(() => this.calendar()?.focusActiveCell(), { injector: this.injector });
  }

  protected chooseLatestWeek(): void {
    this.close();
    this.weekSelected.emit(this.latestCompleteWeek());
  }

  protected choose(day: Date | null): void {
    if (day === null) {
      return;
    }
    const chosenWeek = format(day, ISO_DATE_FORMAT);
    this.close();
    if (chosenWeek !== this.week().start) {
      this.weekSelected.emit(chosenWeek);
    }
  }
}
import { EventType, HealthStatus, SeriesHealth } from '../../core/models';
import { IconName } from './components/icon';

const ACTIVITY_NOUNS: Record<EventType, { singular: string; plural: string }> = {
  all: { singular: 'inbound event', plural: 'inbound events' },
  call_received: { singular: 'call', plural: 'calls' },
  lead_created: { singular: 'lead', plural: 'leads' },
  appointment_set: { singular: 'appointment', plural: 'appointments' },
};

export const EVENT_TYPE_LABELS: Record<EventType, string> = {
  all: 'All activity',
  call_received: 'Calls',
  lead_created: 'Leads',
  appointment_set: 'Appointments',
};

export function activityNoun(count: number, eventType: EventType): string {
  const nouns = ACTIVITY_NOUNS[eventType];
  return count === 1 ? nouns.singular : nouns.plural;
}

export function activityCount(count: number, eventType: EventType): string {
  return `${count} ${activityNoun(count, eventType)}`;
}

export function usualRange(series: SeriesHealth): string | null {
  const { low, high } = series.baseline;
  return series.status === 'insufficient_data' || low === null || high === null ? null : `${low}–${high}`;
}

export function statusLabel(series: SeriesHealth, minimumEligibleWeeks: number): string {
  switch (series.status) {
    case 'above':
      return '▲ Higher than usual';
    case 'below':
      return '▼ Lower than usual';
    case 'normal':
      return 'Within usual range';
    case 'insufficient_data':
      return `Not enough history yet (${series.baseline.weeksUsed} of ${minimumEligibleWeeks} weeks needed)`;
  }
}

export function statusIcon(status: HealthStatus): IconName | null {
  switch (status) {
    case 'normal':
      return 'within-range';
    case 'insufficient_data':
      return 'not-enough-history';
    case 'above':
    case 'below':
      return null;
  }
}
const ISO_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000;
const DAYS_PER_WEEK = 7;
const MONDAY = 1;

interface CalendarDayParts {
  weekday: string;
  month: string;
  day: string;
  year: string;
}

function utcMidnightOf(isoDate: string): Date {
  return new Date(`${isoDate}T00:00:00Z`);
}

function isoDateOf(utcMidnight: Date): string {
  return utcMidnight.toISOString().slice(0, 10);
}

export function isIsoMonday(candidate: string | null): candidate is string {
  if (candidate === null || !ISO_DATE_PATTERN.test(candidate)) {
    return false;
  }
  const parsed = utcMidnightOf(candidate);
  return !Number.isNaN(parsed.getTime()) && isoDateOf(parsed) === candidate && parsed.getUTCDay() === MONDAY;
}

export function addWeeks(weekStart: string, weekCount: number): string {
  return isoDateOf(new Date(utcMidnightOf(weekStart).getTime() + weekCount * DAYS_PER_WEEK * MILLISECONDS_PER_DAY));
}

export function sundayOfWeek(weekStart: string): string {
  return isoDateOf(new Date(utcMidnightOf(weekStart).getTime() + (DAYS_PER_WEEK - 1) * MILLISECONDS_PER_DAY));
}

const calendarDayFormatters = new Map<string, Intl.DateTimeFormat>();

function calendarDayFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = calendarDayFormatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', timeZone });
    calendarDayFormatters.set(timeZone, formatter);
  }
  return formatter;
}

const utcCalendarDayFormatter = calendarDayFormatter('UTC');

function calendarDayParts(instant: Date, formatter: Intl.DateTimeFormat): CalendarDayParts {
  const parts = formatter.formatToParts(instant);
  const partValue = (type: Intl.DateTimeFormatPartTypes): string => parts.find((part) => part.type === type)?.value ?? '';
  return { weekday: partValue('weekday'), month: partValue('month'), day: partValue('day'), year: partValue('year') };
}

function dayWithoutYear(parts: CalendarDayParts): string {
  return `${parts.weekday} ${parts.month} ${parts.day}`;
}

function dayWithYear(parts: CalendarDayParts): string {
  return `${dayWithoutYear(parts)}, ${parts.year}`;
}

function formatCalendarDayPair(firstDay: string, lastDay: string, separator: string): string {
  const firstParts = calendarDayParts(utcMidnightOf(firstDay), utcCalendarDayFormatter);
  const lastParts = calendarDayParts(utcMidnightOf(lastDay), utcCalendarDayFormatter);
  const firstLabel = firstParts.year === lastParts.year ? dayWithoutYear(firstParts) : dayWithYear(firstParts);
  return `${firstLabel}${separator}${dayWithYear(lastParts)}`;
}

export function formatWeekRange(weekStart: string, weekEnd: string): string {
  return formatCalendarDayPair(weekStart, weekEnd, ' – ');
}

export function formatSelectableWeeks(earliestWeek: string, latestCompleteWeek: string): string {
  return `Weeks from ${formatCalendarDayPair(earliestWeek, latestCompleteWeek, ' to ')}`;
}

export function formatCalendarDay(instant: string, timeZone: string): string | null {
  const parsed = new Date(instant);
  return Number.isNaN(parsed.getTime()) ? null : dayWithYear(calendarDayParts(parsed, calendarDayFormatter(timeZone)));
}
